require_once __DIR__.'/document_studio_common.php';$u=uid();try{$id=trim((string)($_GET['document_id']??''));$d=doc($pdo,$id);if($d['requirement_type']!=='RISK')out(['success'=>false,'error'=>'Kein Risikodokument.'],422);$meta=json_decode($d['metadata']??'{}',true)?:[];
if($_SERVER['REQUEST_METHOD']==='GET')out(['success'=>true,'risk'=>$meta['risk']??[]]);
